import { defineStore } from '@mpxjs/pinia'
import { fetchProduct, fetchRecommendations } from '../services/product'

const pendingLoads = new WeakMap()

export const useProductStore = defineStore('product-platform', {
  state: () => ({
    productId: '',
    product: {},
    recommendations: [],
    loading: false,
    error: null
  }),
  actions: {
    async loadProduct (productId, ssrContext) {
      if (!productId) return

      // Hydration and repeated lifecycle hooks reuse the server result.
      if (String(this.productId) === String(productId) && String(this.product.id) === String(productId) && Array.isArray(this.recommendations)) {
        return { product: this.product, recommendations: this.recommendations }
      }

      const pending = pendingLoads.get(this)
      if (pending && pending.productId === productId) return pending.promise

      // A request belongs to the id it started for. The local sequence prevents
      // a slower navigation from publishing data into the newer product.
      const sequence = (this._loadSequence || 0) + 1
      this._loadSequence = sequence
      this.loading = true
      this.error = null
      const promise = (async () => {
        try {
          const [product, recommendations] = await Promise.all([
          fetchProduct(productId, ssrContext),
          fetchRecommendations(productId, ssrContext)
          ])
          if (sequence !== this._loadSequence) return
          this.productId = productId
          this.product = product || {}
          this.recommendations = recommendations || []
          return { product: this.product, recommendations: this.recommendations }
        } catch (error) {
          if (sequence === this._loadSequence) this.error = error
          throw error
        } finally {
          if (sequence === this._loadSequence) this.loading = false
          const current = pendingLoads.get(this)
          if (current && current.promise === promise) pendingLoads.delete(this)
        }
      })()
      pendingLoads.set(this, { productId, promise })
      return promise
    }
  }
})
<template>
  <view class="recommendations">
    <view class="section-title">相关推荐</view>
    <view wx:for="{{items}}" wx:key="id" class="recommendation-card" data-product-id="{{item.id}}" bindtap="openProduct(item.id)">
      <image class="recommendation-cover" src="{{item.cover}}" mode="aspectFill" />
      <text class="recommendation-name">{{item.name}}</text><text class="recommendation-price">¥{{item.price}}</text>
    </view>
  </view>
</template>

<script>
import { createComponent } from '@mpxjs/core'
import mpx from '@mpxjs/api-proxy'
import exposureSdk from '@business/product-exposure-web'

createComponent({
  properties: { productId: String, items: Array },
  data: { tracker: null, observer: null, generation: 0, disposed: false },
  observers: {
    productId (value, previous) {
      if (value !== previous && this._clientReady) this.startTracker()
    }
  },
  ready () {
    this._clientReady = true
    this.startTracker()
  },
  methods: {
    startTracker () {
      if (typeof window === 'undefined' || typeof document === 'undefined' || typeof IntersectionObserver === 'undefined') return
      this.disposed = false
      const generation = ++this.generation
      const productId = this.productId
      if (this.observer) this.observer.disconnect()
      if (this.tracker && this.tracker.destroy) this.tracker.destroy()
      this.observer = null
      this.tracker = null
      this.trackerPromise = Promise.resolve(exposureSdk.create({ productId })).then((tracker) => {
      if (this.disposed || generation !== this.generation || productId !== this.productId) {
        if (tracker && tracker.destroy) tracker.destroy()
        return null
      }
      this.tracker = tracker
      this.observer = new IntersectionObserver((entries) => {
        if (this.disposed || generation !== this.generation || !this.tracker) return
        entries.forEach((entry) => {
          if (entry.isIntersecting) this.tracker.track('recommendation_exposure', { productId, recommendationId: entry.target.dataset.productId })
        })
      })
      document.querySelectorAll('.recommendation-card').forEach(element => this.observer.observe(element))
      return tracker
      })
    },
    openProduct (productId) { mpx.navigateTo({ url: `/packageProduct/pages/detail/index?id=${productId}` }) }
  },
  detached () {
    this.disposed = true
    ++this.generation
    if (this.observer) this.observer.disconnect()
    if (this.tracker && this.tracker.destroy) this.tracker.destroy()
    this.observer = null
    this.tracker = null
  }
})
</script>

